#### Phase 2: Core Implementation (Week 3-6)

**Step 2.1: Implement Job Tracking Domain Model**

Create domain entities for job tracking:

```csharp
// Models/AsyncJob.cs
using System;
using System.Collections.Generic;

namespace Gainwell.Integration.AsyncProcessing.Models
{
    public class AsyncJob
    {
        public string Id { get; set; } = Guid.NewGuid().ToString();
        public string TenantId { get; set; } // Partition key for Cosmos DB
        public string JobType { get; set; }
        public string UserId { get; set; }
        public JobStatus Status { get; set; } = JobStatus.Pending;
        public int ProgressPercentage { get; set; } = 0;
        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
        public DateTime? StartedAt { get; set; }
        public DateTime? CompletedAt { get; set; }
        public TimeSpan? EstimatedDuration { get; set; }
        public TimeSpan? ActualDuration => CompletedAt.HasValue
            ? CompletedAt.Value - CreatedAt
            : null;

        public Dictionary<string, object> Parameters { get; set; } = new();
        public Dictionary<string, object> Results { get; set; } = new();
        public string ResultBlobUrl { get; set; } // For large results

        public List<string> ErrorMessages { get; set; } = new();
        public string ErrorDetails { get; set; }

        public List<JobStatusTransition> StatusHistory { get; set; } = new();
        public JobMetadata Metadata { get; set; } = new();
    }

    public enum JobStatus
    {
        Pending,
        Running,
        Completed,
        Failed,
        Cancelled
    }

    public class JobStatusTransition
    {
        public DateTime Timestamp { get; set; } = DateTime.UtcNow;
        public JobStatus FromStatus { get; set; }
        public JobStatus ToStatus { get; set; }
        public string Reason { get; set; }
    }

    public class JobMetadata
    {
        public string WorkerId { get; set; }
        public int RetryCount { get; set; } = 0;
        public int MaxRetries { get; set; } = 3;
        public string Priority { get; set; } = "Normal";
        public string WebhookUrl { get; set; }
        public DateTime? WebhookDeliveredAt { get; set; }
    }
}
