**Step 2.2: Implement Job Service with Repository Pattern**

```csharp
// Services/IJobService.cs
using Gainwell.Integration.AsyncProcessing.Models;
using System.Threading.Tasks;

namespace Gainwell.Integration.AsyncProcessing.Services
{
    public interface IJobService
    {
        Task<AsyncJob> CreateJobAsync(string tenantId, string jobType,
            string userId, Dictionary<string, object> parameters);
        Task<AsyncJob> GetJobAsync(string tenantId, string jobId);
        Task<AsyncJob> UpdateJobStatusAsync(string tenantId, string jobId,
            JobStatus newStatus, string reason = null);
        Task<AsyncJob> UpdateJobProgressAsync(string tenantId, string jobId,
            int progressPercentage, TimeSpan? estimatedRemaining = null);
        Task<AsyncJob> CompleteJobAsync(string tenantId, string jobId,
            Dictionary<string, object> results, string resultBlobUrl = null);
        Task<AsyncJob> FailJobAsync(string tenantId, string jobId,
            string errorMessage, string errorDetails);
    }
}

// Services/JobService.cs
using Microsoft.Azure.Cosmos;
using Microsoft.Extensions.Logging;
using System;
using System.Threading.Tasks;

namespace Gainwell.Integration.AsyncProcessing.Services
{
    public class JobService : IJobService
    {
        private readonly Container _jobContainer;
        private readonly ILogger<JobService> _logger;

        public JobService(CosmosClient cosmosClient, ILogger<JobService> logger)
        {
            _jobContainer = cosmosClient
                .GetDatabase("JobTracking")
                .GetContainer("Jobs");
            _logger = logger;
        }

        public async Task<AsyncJob> CreateJobAsync(string tenantId,
            string jobType, string userId, Dictionary<string, object> parameters)
        {
            var job = new AsyncJob
            {
                TenantId = tenantId,
                JobType = jobType,
                UserId = userId,
                Parameters = parameters,
                Status = JobStatus.Pending
            };

            // Calculate estimated duration based on historical data
            job.EstimatedDuration = await EstimateDurationAsync(jobType, parameters);

            job.StatusHistory.Add(new JobStatusTransition
            {
                FromStatus = JobStatus.Pending,
                ToStatus = JobStatus.Pending,
                Reason = "Job created"
            });

            await _jobContainer.CreateItemAsync(job,
                new PartitionKey(tenantId));

            _logger.LogInformation(
                "Created job {JobId} of type {JobType} for tenant {TenantId}",
                job.Id, job.JobType, job.TenantId);

            return job;
        }

        public async Task<AsyncJob> GetJobAsync(string tenantId, string jobId)
        {
            try
            {
                var response = await _jobContainer.ReadItemAsync<AsyncJob>(
                    jobId, new PartitionKey(tenantId));
                return response.Resource;
            }
            catch (CosmosException ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
            {
                throw new JobNotFoundException(jobId);
            }
        }

        public async Task<AsyncJob> UpdateJobStatusAsync(string tenantId,
            string jobId, JobStatus newStatus, string reason = null)
        {
            var job = await GetJobAsync(tenantId, jobId);
            var oldStatus = job.Status;

            job.Status = newStatus;
            job.StatusHistory.Add(new JobStatusTransition
            {
                FromStatus = oldStatus,
                ToStatus = newStatus,
                Reason = reason ?? $"Status changed to {newStatus}"
            });

            if (newStatus == JobStatus.Running && !job.StartedAt.HasValue)
            {
                job.StartedAt = DateTime.UtcNow;
            }

            await _jobContainer.ReplaceItemAsync(job, job.Id,
                new PartitionKey(tenantId));

            _logger.LogInformation(
                "Job {JobId} status changed from {OldStatus} to {NewStatus}",
                jobId, oldStatus, newStatus);

            return job;
        }

        public async Task<AsyncJob> UpdateJobProgressAsync(string tenantId,
            string jobId, int progressPercentage, TimeSpan? estimatedRemaining = null)
        {
            var job = await GetJobAsync(tenantId, jobId);
            job.ProgressPercentage = Math.Clamp(progressPercentage, 0, 100);

            if (estimatedRemaining.HasValue)
            {
                job.EstimatedDuration = estimatedRemaining;
            }

            await _jobContainer.ReplaceItemAsync(job, job.Id,
                new PartitionKey(tenantId));

            return job;
        }

        public async Task<AsyncJob> CompleteJobAsync(string tenantId,
            string jobId, Dictionary<string, object> results, string resultBlobUrl = null)
        {
            var job = await GetJobAsync(tenantId, jobId);

            job.Status = JobStatus.Completed;
            job.CompletedAt = DateTime.UtcNow;
            job.ProgressPercentage = 100;
            job.Results = results;
            job.ResultBlobUrl = resultBlobUrl;

            job.StatusHistory.Add(new JobStatusTransition
            {
                FromStatus = JobStatus.Running,
                ToStatus = JobStatus.Completed,
                Reason = "Job completed successfully"
            });

            await _jobContainer.ReplaceItemAsync(job, job.Id,
                new PartitionKey(tenantId));

            _logger.LogInformation(
                "Job {JobId} completed in {Duration}",
                jobId, job.ActualDuration);

            return job;
        }

        public async Task<AsyncJob> FailJobAsync(string tenantId,
            string jobId, string errorMessage, string errorDetails)
        {
            var job = await GetJobAsync(tenantId, jobId);

            job.Status = JobStatus.Failed;
            job.CompletedAt = DateTime.UtcNow;
            job.ErrorMessages.Add(errorMessage);
            job.ErrorDetails = errorDetails;

            job.StatusHistory.Add(new JobStatusTransition
            {
                FromStatus = JobStatus.Running,
                ToStatus = JobStatus.Failed,
                Reason = errorMessage
            });

            await _jobContainer.ReplaceItemAsync(job, job.Id,
                new PartitionKey(tenantId));

            _logger.LogError(
                "Job {JobId} failed: {ErrorMessage}",
                jobId, errorMessage);

            return job;
        }

        private async Task<TimeSpan> EstimateDurationAsync(string jobType,
            Dictionary<string, object> parameters)
        {
            // Query historical job durations for this job type
            // Apply ML model or statistical analysis to predict duration
            // Simplified implementation returns fixed estimates
            return jobType switch
            {
                "ClaimsReprocessing" => TimeSpan.FromMinutes(5),
                "ProviderCredentialing" => TimeSpan.FromMinutes(3),
                "ReportGeneration" => TimeSpan.FromMinutes(2),
                _ => TimeSpan.FromMinutes(1)
            };
        }
    }

    public class JobNotFoundException : Exception
    {
        public JobNotFoundException(string jobId)
            : base($"Job {jobId} not found") { }
    }
}
