**Step 2.4: Implement Background Worker (Azure Function)**

```csharp
// Functions/ClaimsReprocessingWorker.cs
using Azure.Messaging.ServiceBus;
using Gainwell.Integration.AsyncProcessing.Models;
using Gainwell.Integration.AsyncProcessing.Services;
using Microsoft.Azure.Functions.Worker;
using Microsoft.Extensions.Logging;
using System;
using System.Collections.Generic;
using System.Text.Json;
using System.Threading.Tasks;

namespace Gainwell.AsyncWorkers.Functions
{
    public class ClaimsReprocessingWorker
    {
        private readonly IJobService _jobService;
        private readonly IClaimsService _claimsService;
        private readonly ILogger<ClaimsReprocessingWorker> _logger;

        public ClaimsReprocessingWorker(
            IJobService jobService,
            IClaimsService claimsService,
            ILogger<ClaimsReprocessingWorker> logger)
        {
            _jobService = jobService;
            _claimsService = claimsService;
            _logger = logger;
        }

        [Function(nameof(ProcessClaimsReprocessingJob))]
        public async Task ProcessClaimsReprocessingJob(
            [ServiceBusTrigger("job-processing", "job-processor-subscription",
                Connection = "ServiceBusConnection")]
            ServiceBusReceivedMessage message,
            ServiceBusMessageActions messageActions)
        {
            var jobMessage = JsonSerializer.Deserialize<JobMessage>(
                message.Body.ToString());

            _logger.LogInformation(
                "Processing job {JobId} of type {JobType}",
                jobMessage.JobId, jobMessage.JobType);

            try
            {
                // Update job status to Running
                await _jobService.UpdateJobStatusAsync(
                    jobMessage.TenantId,
                    jobMessage.JobId,
                    JobStatus.Running,
                    $"Started by worker {Environment.MachineName}");

                // Extract parameters
                var claimIds = JsonSerializer.Deserialize<List<string>>(
                    jobMessage.Parameters["claimIds"].ToString());
                var reason = jobMessage.Parameters["reason"].ToString();

                // Process claims with progress tracking
                var totalClaims = claimIds.Count;
                var processedClaims = 0;
                var successfulClaims = 0;
                var failedClaims = new List<string>();

                foreach (var claimId in claimIds)
                {
                    try
                    {
                        await _claimsService.ReprocessClaimAsync(
                            jobMessage.TenantId, claimId, reason);
                        successfulClaims++;
                    }
                    catch (Exception ex)
                    {
                        _logger.LogWarning(ex,
                            "Failed to reprocess claim {ClaimId}", claimId);
                        failedClaims.Add(claimId);
                    }

                    processedClaims++;

                    // Update progress every 10% or every 100 claims
                    if (processedClaims % 100 == 0 ||
                        processedClaims * 100 / totalClaims % 10 == 0)
                    {
                        var progressPercentage = processedClaims * 100 / totalClaims;
                        var remainingClaims = totalClaims - processedClaims;
                        var estimatedRemaining = TimeSpan.FromSeconds(
                            remainingClaims * 0.5); // Estimate 0.5s per claim

                        await _jobService.UpdateJobProgressAsync(
                            jobMessage.TenantId,
                            jobMessage.JobId,
                            progressPercentage,
                            estimatedRemaining);

                        _logger.LogInformation(
                            "Job {JobId} progress: {Progress}% ({Processed}/{Total})",
                            jobMessage.JobId, progressPercentage,
                            processedClaims, totalClaims);
                    }
                }

                // Complete job with results
                var results = new Dictionary<string, object>
                {
                    ["totalClaims"] = totalClaims,
                    ["successfulClaims"] = successfulClaims,
                    ["failedClaims"] = failedClaims.Count,
                    ["failedClaimIds"] = failedClaims,
                    ["completedAt"] = DateTime.UtcNow
                };

                await _jobService.CompleteJobAsync(
                    jobMessage.TenantId,
                    jobMessage.JobId,
                    results);

                // Complete message (remove from queue)
                await messageActions.CompleteMessageAsync(message);

                _logger.LogInformation(
                    "Job {JobId} completed successfully. " +
                    "Processed {Total} claims: {Successful} successful, {Failed} failed",
                    jobMessage.JobId, totalClaims, successfulClaims,
                    failedClaims.Count);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex,
                    "Job {JobId} failed with error", jobMessage.JobId);

                // Update job status to Failed
                await _jobService.FailJobAsync(
                    jobMessage.TenantId,
                    jobMessage.JobId,
                    ex.Message,
                    ex.StackTrace);

                // Check retry count
                var job = await _jobService.GetJobAsync(
                    jobMessage.TenantId, jobMessage.JobId);

                if (job.Metadata.RetryCount < job.Metadata.MaxRetries)
                {
                    // Abandon message for retry
                    job.Metadata.RetryCount++;
                    await messageActions.AbandonMessageAsync(message);

                    _logger.LogWarning(
                        "Job {JobId} abandoned for retry {RetryCount}/{MaxRetries}",
                        jobMessage.JobId, job.Metadata.RetryCount,
                        job.Metadata.MaxRetries);
                }
                else
                {
                    // Max retries exceeded, move to dead-letter queue
                    await messageActions.DeadLetterMessageAsync(
                        message,
                        deadLetterReason: "MaxRetriesExceeded",
                        deadLetterErrorDescription: ex.Message);

                    _logger.LogError(
                        "Job {JobId} moved to dead-letter queue after " +
                        "{MaxRetries} failed attempts",
                        jobMessage.JobId, job.Metadata.MaxRetries);
                }
            }
        }
    }

    public class JobMessage
    {
        public string JobId { get; set; }
        public string TenantId { get; set; }
        public string JobType { get; set; }
        public Dictionary<string, object> Parameters { get; set; }
    }
}
