**Step 2.5: Implement Job Status API**

```csharp
// Controllers/JobsController.cs
using Gainwell.Integration.AsyncProcessing.Models;
using Gainwell.Integration.AsyncProcessing.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using System;
using System.Threading.Tasks;

namespace Gainwell.ClaimsAPI.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class JobsController : ControllerBase
    {
        private readonly IJobService _jobService;
        private readonly ILogger<JobsController> _logger;

        public JobsController(
            IJobService jobService,
            ILogger<JobsController> logger)
        {
            _jobService = jobService;
            _logger = logger;
        }

        /// <summary>
        /// Get job status and progress
        /// </summary>
        [HttpGet("{jobId}")]
        [ProducesResponseType(typeof(JobStatusResponse), StatusCodes.Status200OK)]
        [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound)]
        public async Task<IActionResult> GetJobStatusAsync(string jobId)
        {
            var tenantId = User.FindFirst("tenantId")?.Value
                ?? throw new UnauthorizedAccessException();

            try
            {
                var job = await _jobService.GetJobAsync(tenantId, jobId);

                // Set cache headers based on job status
                if (job.Status == JobStatus.Completed ||
                    job.Status == JobStatus.Failed)
                {
                    // Completed jobs are immutable, cache for 1 hour
                    Response.Headers.CacheControl = "public, max-age=3600";
                    Response.Headers.ETag = $"\"{job.Id}-{job.CompletedAt:O}\"";
                }
                else
                {
                    // Running/pending jobs should not be cached
                    Response.Headers.CacheControl = "no-cache, no-store, must-revalidate";

                    // Suggest next poll interval based on estimated completion
                    if (job.EstimatedDuration.HasValue)
                    {
                        var remainingTime = job.EstimatedDuration.Value -
                            (DateTime.UtcNow - job.CreatedAt);
                        var pollInterval = remainingTime.TotalSeconds < 30
                            ? 2  // Poll every 2 seconds for jobs finishing soon
                            : 5; // Poll every 5 seconds for longer jobs
                        Response.Headers["Retry-After"] = pollInterval.ToString();
                    }
                }

                var response = new JobStatusResponse
                {
                    JobId = job.Id,
                    Status = job.Status.ToString(),
                    ProgressPercentage = job.ProgressPercentage,
                    CreatedAt = job.CreatedAt,
                    StartedAt = job.StartedAt,
                    CompletedAt = job.CompletedAt,
                    EstimatedRemainingSeconds = job.EstimatedDuration.HasValue
                        ? (int?)Math.Max(0, (job.EstimatedDuration.Value -
                            (DateTime.UtcNow - job.CreatedAt)).TotalSeconds)
                        : null,
                    Results = job.Status == JobStatus.Completed
                        ? job.Results
                        : null,
                    ResultsUrl = !string.IsNullOrEmpty(job.ResultBlobUrl)
                        ? job.ResultBlobUrl
                        : null,
                    ErrorMessage = job.Status == JobStatus.Failed
                        ? string.Join("; ", job.ErrorMessages)
                        : null
                };

                return Ok(response);
            }
            catch (JobNotFoundException)
            {
                return NotFound(new ProblemDetails
                {
                    Title = "Job not found",
                    Detail = $"Job {jobId} not found",
                    Status = StatusCodes.Status404NotFound
                });
            }
        }

        /// <summary>
        /// Get job results (for completed jobs)
        /// </summary>
        [HttpGet("{jobId}/results")]
        [ProducesResponseType(typeof(object), StatusCodes.Status200OK)]
        [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound)]
        [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict)]
        public async Task<IActionResult> GetJobResultsAsync(string jobId)
        {
            var tenantId = User.FindFirst("tenantId")?.Value
                ?? throw new UnauthorizedAccessException();

            try
            {
                var job = await _jobService.GetJobAsync(tenantId, jobId);

                if (job.Status != JobStatus.Completed)
                {
                    return Conflict(new ProblemDetails
                    {
                        Title = "Job not completed",
                        Detail = $"Job is currently {job.Status}. " +
                                "Results are only available for completed jobs.",
                        Status = StatusCodes.Status409Conflict
                    });
                }

                // For large results stored in blob storage
                if (!string.IsNullOrEmpty(job.ResultBlobUrl))
                {
                    return Ok(new
                    {
                        jobId = job.Id,
                        status = job.Status.ToString(),
                        resultType = "blob",
                        downloadUrl = job.ResultBlobUrl,
                        expiresAt = DateTime.UtcNow.AddHours(1)
                    });
                }

                // For inline results
                return Ok(new
                {
                    jobId = job.Id,
                    status = job.Status.ToString(),
                    resultType = "inline",
                    results = job.Results
                });
            }
            catch (JobNotFoundException)
            {
                return NotFound(new ProblemDetails
                {
                    Title = "Job not found",
                    Detail = $"Job {jobId} not found",
                    Status = StatusCodes.Status404NotFound
                });
            }
        }
    }

    public class JobStatusResponse
    {
        public string JobId { get; set; }
        public string Status { get; set; }
        public int ProgressPercentage { get; set; }
        public DateTime CreatedAt { get; set; }
        public DateTime? StartedAt { get; set; }
        public DateTime? CompletedAt { get; set; }
        public int? EstimatedRemainingSeconds { get; set; }
        public object Results { get; set; }
        public string ResultsUrl { get; set; }
        public string ErrorMessage { get; set; }
    }
}
