using Gainwell.Integration.AsyncProcessing.Models;

namespace Gainwell.AsyncProcessing.Tests.Services
{
    public class JobServiceTests
    {
        [Fact]
        public async Task CreateJobAsync_ShouldCreateJobWithPendingStatus()
        {
            // Arrange
            var tenantId = "tenant-123";
            var jobType = "ClaimsReprocessing";
            var userId = "user-456";
            var parameters = new Dictionary<string, object>
            {
                ["claimIds"] = new List<string> { "claim-1", "claim-2" }
            };

            // Act
            var job = await _jobService.CreateJobAsync(
                tenantId, jobType, userId, parameters);

            // Assert
            job.Should().NotBeNull();
            job.Id.Should().NotBeNullOrEmpty();
            job.TenantId.Should().Be(tenantId);
            job.JobType.Should().Be(jobType);
            job.UserId.Should().Be(userId);
            job.Status.Should().Be(JobStatus.Pending);
            job.Parameters.Should().BeEquivalentTo(parameters);
            job.EstimatedDuration.Should().NotBeNull();
            job.StatusHistory.Should().HaveCount(1);
        }

        [Fact]
        public async Task UpdateJobProgressAsync_ShouldUpdateProgressPercentage()
        {
            // Arrange
            var job = await CreateTestJobAsync();

            // Act
